import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, DoubleSide } = ctx.THREE;

  const group = new Group();
  group.position.set(0, -0.35, -0.6);

  // Atlas region aspect: 512x320 = 1.6:1
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Atlas UV mapping for region [0,0,512,320] in a 2048x2048 sheet
  const uvAttribute = geometry.getAttribute('uv');
  const uMin = 0 / 2048;
  const uMax = 512 / 2048;
  const vMin = 0 / 2048;
  const vMax = 320 / 2048;

  for (let i = 0; i < uvAttribute.count; i++) {
    const u = uvAttribute.getX(i);
    const v = uvAttribute.getY(i);
    uvAttribute.setXY(i, uMin + u * (uMax - uMin), vMin + v * (vMax - vMin));
  }
  uvAttribute.needsUpdate = true;

  let mesh;
  let materialLoaded;

  // Placeholder material
  const materialPlaceholder = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    side: DoubleSide,
  });

  mesh = new Mesh(geometry, materialPlaceholder);
  group.add(mesh);

  // Load texture and apply
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    const materialFinal = new MeshBasicNodeMaterial({
      map: texture,
      transparent: true,
      side: DoubleSide,
    });
    mesh.material = materialFinal;
    materialLoaded = materialFinal;
  });

  // Billboard constraint (update in render loop via animation frame)
  const billboardUpdate = () => {
    if (ctx.camera) {
      mesh.lookAt(ctx.camera.position);
    }
  };

  group.userData.handlers = {
    beforeRender: billboardUpdate,
  };

  group.userData.cleanup = () => {
    geometry.dispose();
    materialPlaceholder.dispose();
    if (materialLoaded) materialLoaded.dispose();
  };

  return group;
}
